function isAdultWorker(age: number): boolean {
	return age >= 18 && age <= 65;
}
// pruebas de frontera: 17 -> false, 18 -> true, 65 -> true, 66 -> false

function price(base: number, student: boolean, voucher: boolean): number {
	let total = base;
	if (student) total -= 5;
	if (voucher) total -= 3;
	return total;
}

